import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    und_lucky_set = set()
    digits = [str(i) for i in range(10)]

    for x in range(10):
        for y in range(10):
            allowed = {digits[x], digits[y]}
            first_digits = [d for d in allowed if d != '0']
            if not first_digits:
                continue
            stack = first_digits[:]
            while stack:
                s = stack.pop()
                val = int(s)
                if val > n:
                    continue
                und_lucky_set.add(val)
                if len(s) < 10:
                    for d in allowed:
                        stack.append(s + d)

    print(len(und_lucky_set))

if __name__ == "__main__":
    main()
